package com.example.rokidkeyboardbridge;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
public final class GlassReservationChecks {
 static int n;static void ok(boolean v){n++;if(!v)throw new AssertionError("glass reservation "+n);}static String id(){return UUID.randomUUID().toString();}
 public static JSONArray receipt(Context c,String id)throws Exception{ReservationProgress.begin(c,id,"photo","ACCEPTED","accepted");String batch=TransferProgressStore.begin(c,"photo");TransferProgressStore.update(c,"photo",batch,"COMPLETED",2,2,0,0,0,2,2);return ReservationProgress.snapshot(c);}
 public static int run(Context c)throws Exception{String reservation=id();ReservationProgress.begin(c,reservation,"photo","ACCEPTED","accepted");JSONArray rows=ReservationProgress.snapshot(c);JSONObject accepted=rows.getJSONObject(rows.length()-1);ok(accepted.getString("phase").equals("ACCEPTED"));ok(!accepted.has("process"));String batch=TransferProgressStore.begin(c,"photo");JSONObject running=ReservationProgress.snapshot(c).getJSONObject(rows.length()-1);ok(running.getString("batchId").equals(batch));ok(running.getString("phase").equals("RUNNING"));TransferProgressStore.update(c,"photo",batch,"RUNNING",2,1,0,0,0,2,1);JSONObject progress=ReservationProgress.snapshot(c).getJSONObject(rows.length()-1);ok(progress.getLong("confirmed")==1);TransferProgressStore.update(c,"photo",batch,"COMPLETED",2,1,0,0,0,2,1);ok(ReservationProgress.snapshot(c).getJSONObject(rows.length()-1).getString("phase").equals("PARTIAL"));ReservationProgress.begin(c,reservation,"photo","ACCEPTED","duplicate");ok(ReservationProgress.snapshot(c).length()==rows.length());String unrelated=TransferProgressStore.begin(c,"photo");TransferProgressStore.update(c,"photo",unrelated,"COMPLETED",0,0,0,0,0,0,0);ok(ReservationProgress.snapshot(c).getJSONObject(rows.length()-1).getString("phase").equals("PARTIAL"));String second=id();ReservationProgress.begin(c,second,"meeting","REJECTED","recording");ok(ReservationProgress.snapshot(c).getJSONObject(rows.length()).getString("phase").equals("REJECTED"));String third=id();ReservationProgress.begin(c,third,"meeting","ACCEPTED","accepted");ReservationProgress.unstarted(c,"meeting");ok(ReservationProgress.snapshot(c).getJSONObject(rows.length()+1).getString("phase").equals("FAILED"));String fourth=id();ReservationProgress.begin(c,fourth,"photo","ACCEPTED","accepted");JSONArray stored=ReservationProgress.rows(c);stored.getJSONObject(stored.length()-1).put("process","old-process");ReservationProgress.write(c,stored);ok(ReservationProgress.snapshot(c).getJSONObject(stored.length()-1).getString("phase").equals("INTERRUPTED"));String afterRestart=TransferProgressStore.begin(c,"photo");TransferProgressStore.update(c,"photo",afterRestart,"COMPLETED",1,1,0,0,0,1,1);ok(ReservationProgress.snapshot(c).getJSONObject(stored.length()-1).getString("phase").equals("INTERRUPTED"));for(int i=0;i<12;i++)ReservationProgress.begin(c,id(),"photo","EXPIRED","expired");ok(ReservationProgress.snapshot(c).length()==8);return n;}
}
